use xiom.io;
type Photo = {
  id: Int;
  tags: Set[Str];
}

fn add_tag(photo: &mut Photo, tag: Str) {
  photo.tags.insert(tag);
}

fn has_any_tag(photo: &Photo, search_tags: &Vec[Str]) -> Bool {
  let i = 0;
  while i < search_tags.len() {
    let tag = match search_tags.get(i) { Some(t) => t, None => "" };
    if photo.tags.contains(&tag) {
      return true;
    }
    i = i + 1;
  }
  return false;
}

fn main() -> Int {
  let mut photo = Photo{ id: 42, tags: Set[Str].new() };
  add_tag(&mut photo, "nature");
  add_tag(&mut photo, "sunset");
  add_tag(&mut photo, "ocean");
  add_tag(&mut photo, "nature");

  io.println(photo.tags.contains(&"nature").to_str());

  let search: Vec[Str] = Vec[Str].new();
  search.push("urban");
  search.push("ocean");
  io.println((has_any_tag(&photo, &search)).to_str());
  return 0;
}
